var crystalShader
var noiseShader
var canvas
var rawReflections
var reflections
var r = 200

function preload() {
	rawReflections = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/studio_small_08_min.jpg')
}

function setup() {
	canvas = createCanvas(600, 600, WEBGL)
	crystalShader = createShader(...createCrystalShader())
	noiseShader = createShader(...createNoiseShader())

	const reflectionGraphic = createGraphics(600, 600*rawReflections.height/rawReflections.width)
	reflectionGraphic.background(0)
	reflectionGraphic.drawingContext.filter = 'blur(20px)'
	reflectionGraphic.image(rawReflections, 0, 0, reflectionGraphic.width, reflectionGraphic.height)
	reflections = reflectionGraphic.get()
	reflectionGraphic.remove()

	drawingContext.enable(drawingContext.BLEND)
	drawingContext.disable(drawingContext.DEPTH_TEST)
}

function draw() {
	clear()
	background(0)
	const t = millis()

	noStroke()

	push()
	ambientLight(20)
	pointLight(30, 30, 30, width*0.2, -height, 0)
	pointLight(40, 40, 40, -width*0.1, -height, 0)
	//lights()
	specularMaterial('#4d372b')
	translate(0, r)
	rotateX(PI * 0.3)
	plane(2000, 2000)
	pop()

	push()
	fill(255)
	shader(noiseShader)
	noiseShader.setUniform('time', t)
	rectMode(CENTER); rect(0, 0, 2 * r, 2 * r)
	pop()

	push()
	rotateX(t * 0.00005)
	rotateY(t * 0.0001)
	drawingContext.enable(drawingContext.CULL_FACE)
	drawingContext.cullFace(drawingContext.FRONT)
	shader(crystalShader)
  crystalShader.setUniform('backContent', canvas)
  crystalShader.setUniform('pixelSize', [width * pixelDensity(), height * pixelDensity()])
  crystalShader.setUniform('reflections', reflections)
	sphere(r, 36, 36)
	drawingContext.disable(drawingContext.CULL_FACE)
	pop()
}
